import{_ as t,o as e,a as l,b as i}from"./app.DKoEZOcr.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"矩阵计算","link":"/api/SIMD-API/adv_api/cube_compute/cube_compute"},{"text":"Matmul核函数（Kernel）侧接口","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/Matmul_Kernel"},{"text":"GetMatmulApiTiling","link":"/api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/GetMatmulApiTiling"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/GetMatmulApiTiling.md","filePath":"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/GetMatmulApiTiling.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787294517000}'),s={name:"api/SIMD-API/adv_api/cube_compute/Matmul_Kernel/GetMatmulApiTiling.md"};function n(r,a,d,p,h,o){return e(),l("div",null,[...a[0]||(a[0]=[i(`<div><article class="markdown-body"><h1>GetMatmulApiTiling</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>本接口用于在编译期间获取常量化的Matmul Tiling参数。</p><p>Matmul Tiling常量化功能为在编译期期间获取常量化的Matmul Tiling参数并进行算子编译，从而减少Scalar计算开销，提升算子整体性能。具体为，在获取<a href="Matmul_template_params.html">Matmul模板</a>时，可以确定<a href="MatmulConfig.html">MatmulConfig</a>的singleCore Shape（<a href="MatmulConfig.html">MatmulConfig</a>中的singleCoreM/singleCoreN/singleCoreK）和Base Shape（<a href="MatmulConfig.html">MatmulConfig</a>中的basicM/basicN/basicK）参数，或者只确定Base Shape参数；通过指定获取模板的接口中的singleCore Shape和Base Shape参数，或者只指定Base Shape参数，获取自定义模板；然后调用本接口，得到常量化的Matmul Tiling参数。</p><p>当在调用<a href="MatmulConfig.html">获取MatmulConfig模板的接口</a>时，只将(baseM, baseN, baseK)设置为常数值时，称为部分常量化，此时(singleCoreM, singleCoreN, singleCoreK)都保持默认值0，部分常量化场景在核函数（Kernel）侧使用<a href="REGIST_MATMUL_OBJ.html">REGIST_MATMUL_OBJ</a>初始化Matmul对象时，仍需要使用Tiling；将(baseM, baseN, baseK, singleCoreM, singleCoreN, singleCoreK)都设置为常数值时，称为全量常量化，这时可以在<a href="REGIST_MATMUL_OBJ.html">REGIST_MATMUL_OBJ</a>的入参传递Tiling参数的位置，使用空指针替代。</p><p>经过上述部分常量化或全部常量化后，将得到带有常量化参数的MatmulConfig模板，然后使用本接口将Tiling参数常量化。本接口的返回值包含常量化的Matmul Tiling参数和MatmulConfig模板。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>template&lt;class A_TYPE, class B_TYPE, class C_TYPE, class BIAS_TYPE&gt;
__aicore__ constexpr MatmulApiStaticTiling GetMatmulApiTiling(const MatmulConfig&amp; mmCFG, int32_t l1Size = Impl::L1_SIZE)
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>A_TYPE</td><td>A矩阵类型信息，通过<a href="Matmul_usage.html#table1188045714378">MatmulType</a>来定义。</td></tr><tr><td>B_TYPE</td><td>B矩阵类型信息，通过<a href="Matmul_usage.html#table1188045714378">MatmulType</a>来定义。</td></tr><tr><td>C_TYPE</td><td>C矩阵类型信息，通过<a href="Matmul_usage.html#table1188045714378">MatmulType</a>来定义。</td></tr><tr><td>BIAS_TYPE</td><td>BIAS矩阵类型信息，通过<a href="Matmul_usage.html#table1188045714378">MatmulType</a>来定义。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>mmCFG</td><td>输入</td><td>获取的<a href="MatmulConfig.html#matmulconfig-params">MatmulConfig</a>模板。<span data-filter="950"><br><br>对于Ascend 950PR/Ascend 950DT，支持常量化的为全部模板：Norm, IBShare, MDL模板。</span><span data-filter="A3"><br><br>对于Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持常量化的模板有：Norm, MDL模板。</span><span data-filter="910b"><br><br>对于Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持常量化的模板有：Norm, MDL模板。</span><span data-filter="x90"><br><br>对于Kirin X90，支持常量化的模板有：Norm, MDL模板。</span></td></tr><tr><td>l1Size</td><td>输入</td><td>可用的L1大小，默认值L1_SIZE。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p><a href="Matmul_template_params.html#table7939847143412">MatmulApiStaticTiling</a></p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>入参mmCFG，在调用获取MatmulConfig模板的接口获取时，需要使用常数值指定(baseM, baseN, baseK)或者指定(baseM, baseN, baseK, singleCoreM, singleCoreN, singleCoreK)，并且指定的参数值需要和Tiling计算的值保持一致。</li><li>Batch Matmul场景支持全量常量化，但不支持使用空指针替代REGIST_MATMUL_OBJ的入参Tiling。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// 定义Matmul对象
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; aType;
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, half&gt; bType;
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; cType;
typedef AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, float&gt; biasType;
// 这里CFG使用GetNormalConfig接口获取，并指定已知的singleshape信息和baseM,baseN,baseK，指定的数值跟运行时tiling保持一致
// 该示例L1 Buffer可用大小为512KB
constexpr auto staticTiling = GetMatmulApiTiling&lt;aType, bType, cType, biasType&gt;(CFG, 524288);
AscendC::Matmul&lt;aType, bType, cType, biasType, staticTiling&gt; mm;
</code></pre></div></article></div>`,1)])])}const c=t(s,[["render",n]]);export{u as __pageData,c as default};
